import { dirname } from "path";
import { fileURLToPath } from "url";
import { FlatCompat } from "@eslint/eslintrc";

const compat = new FlatCompat({ baseDirectory: dirname(fileURLToPath(import.meta.url)) });

const config = [
  ...compat.extends("next/core-web-vitals", "next/typescript"),
  // next-env.d.ts is generated by Next on every build and is not ours to lint.
  { ignores: ["out/**", ".next/**", "node_modules/**", "next-env.d.ts"] },
  {
    rules: {
      // next/image is a server. This is a static export served by Caddy, so every
      // image is a plain <img> pointed at a file the pipeline already wrote at the
      // right size (rank.draw_evidence). The rule is off because the alternative it
      // recommends does not exist on this deployment.
      "@next/next/no-img-element": "off",
    },
  },
];

export default config;
